import re
from datetime import datetime

documents = [
    {"id": "d1", "text": "Refund policy update", "date": "2026-06-15", "category": "billing"},
    {"id": "d2", "text": "Shipping delays notice", "date": "2025-01-10", "category": "logistics"},
    {"id": "d3", "text": "New refund exceptions", "date": "2026-06-28", "category": "billing"},
]

def parse_structured_intent(query):
    if "last month" in query.lower():
        return {"month": "2026-06"}
    return {}

def apply_metadata_filter(documents, intent):
    if "month" in intent:
        return [d for d in documents if d["date"].startswith(intent["month"])]
    return documents

query = "refund updates from last month"
intent = parse_structured_intent(query)
print(f"Query: {query!r}")
print(f"Parsed structured intent: {intent}\n")

filtered = apply_metadata_filter(documents, intent)
print(f"Documents after metadata filter:")
for d in filtered:
    print(f"  {d}")
